import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
import { loadFont as loadFraunces } from "@remotion/google-fonts/Fraunces";
import { loadFont as loadNunito } from "@remotion/google-fonts/Nunito";

// ANA ULTRAFOCUS · Dra. Laís Verbicaro · v2. Pedido: "mais motions" e a narração na o locutor padrão em português
// brasileiro (regravada no eleven_multilingual_v2, 21,9 s, entra em 0,2 s). Agora metade das cenas é motion desenhado
// (abertura cinética, agenda, dente com escova, WhatsApp, fecho) alternando com os vídeos, que ganharam adesivos animados.
// Base da v1 (LaisVerbicaro.tsx): Pedido: a frase do anúncio ("O sorriso dos pequenos merece cuidado desde cedo"),
// acompanhamento, agende a consulta, telefone, "Atendemos Bradesco Odonto e Particular", trechos curtos de cada vídeo,
// sem a parte da cárie, com o logo da clínica e o da Dra.
// Identidade do logo e do anúncio: creme, vinho, rosa, verde-folha e laranja; Fraunces (títulos) e Nunito.
// Vídeo cheio com lettering embaixo, intercalado com cenas desenhadas (ícones, logos, fecho).
// Tempos = tempo da palavra na voz ((arquivo do cliente)).

const { fontFamily: SERIF } = loadFraunces("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadNunito("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const LV2_FPS = 30;
const LEAD = 0.2;
export const LV2_FRAMES = Math.round(24.4 * LV2_FPS);
const fr = (s: number) => Math.max(0, Math.round((s + LEAD) * LV2_FPS));

const CREAM = "#FFF8F3";
const BLUSH = "#FDE9EF";
const WINE = "#7E1630";
const PINK = "#E6246E";
const PINK_SOFT = "#F7CFDF";
const LEAF = "#CFDC92";
const ORANGE = "#E9532A";
const SHADOW = "0 18px 50px rgba(126,22,48,0.18)";
const SHADOW_D = "0 24px 60px rgba(60,10,25,0.35)";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const INOUT = Easing.inOut(Easing.cubic);
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const k = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: Easing.out(Easing.cubic) });
// entrada com impulso (passa um pouco e volta)
const pop = (t: number, a: number, d: number) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: Easing.out(Easing.back(1.7)) });

// trocas de cena (tempo da voz)
const A1 = 1.08, A2 = 2.88, A3 = 4.42, A4 = 6.45, A5 = 9.1, A6 = 11.45, A7 = 13.95, A8 = 16.6, A9 = 19.35, A10 = 21.3, END = 24.2;

// ───────── peças ─────────
const Clip: React.FC<{ t: number; a: number; b: number; src: string; zoom: [number, number]; origin?: string; pan?: [number, number]; ty?: number }> = ({ t, a, b, src, zoom, origin = "50% 40%", pan = [0, 0], ty = 0 }) => {
  const p = interpolate(t, [a - 0.35, b + 0.35], [0, 1], { ...cl, easing: Easing.inOut(Easing.sin) });
  return (
    <AbsoluteFill style={{ background: WINE, overflow: "hidden" }}>
      <Sequence from={fr(a - 0.35)} layout="none">
        <OffthreadVideo muted src={staticFile(`anaultrafocus/${src}.mp4`)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `translate(${(pan[0] + (pan[1] - pan[0]) * p).toFixed(1)}px, ${ty}px) scale(${(zoom[0] + (zoom[1] - zoom[0]) * p).toFixed(4)})`, transformOrigin: origin }} />
      </Sequence>
    </AbsoluteFill>
  );
};
const Shade: React.FC = () => (
  <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 760, background: "linear-gradient(0deg, rgba(70,10,28,0.55) 0%, rgba(70,10,28,0.25) 55%, rgba(70,10,28,0) 100%)" }} />
);

// lettering embaixo: bloco creme com duas linhas; a segunda linha leva a palavra de destaque em rosa
type Line = { text: React.ReactNode; at: number };
const Lettering: React.FC<{ t: number; lines: Line[]; top?: number; size?: number; out?: number }> = ({ t, lines, top = 1370, size = 92, out }) => {
  const box = pop(t, lines[0].at - 0.12, 0.45);
  const gone = out === undefined ? 0 : lin(t, out - 0.15, out + 0.05);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", justifyContent: "center", opacity: Math.min(1, box * 2) * (1 - gone) }}>
      <div style={{ background: CREAM, borderRadius: 48, padding: "36px 50px 42px", boxShadow: SHADOW_D, textAlign: "center", transform: `scale(${(0.8 + 0.2 * box).toFixed(4)})`, transformOrigin: "50% 50%" }}>
        {lines.map((l, i) => {
          const e = k(t, Math.max(l.at - 0.12, lines[0].at - 0.12), 0.3);
          return (
            <div key={i} style={{ fontFamily: SERIF, fontWeight: 800, fontSize: size, lineHeight: 1.08, color: WINE, letterSpacing: -1, whiteSpace: "nowrap", opacity: e, filter: e < 1 ? `blur(${((1 - e) * 12).toFixed(1)}px)` : undefined }}>{l.text}</div>
          );
        })}
      </div>
    </div>
  );
};
const Hi: React.FC<{ children: React.ReactNode }> = ({ children }) => <span style={{ color: PINK }}>{children}</span>;


// ícones desenhados (linha vinho, como no anúncio)
const IcoShield: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill="none" stroke={WINE} strokeWidth={3.2} strokeLinecap="round" strokeLinejoin="round">
    <path d="M24 5l15 5.5v11.5c0 10-6.6 17.6-15 21-8.4-3.4-15-11-15-21V10.5z" />
    <path d="M24 32s-7-4.3-7-9a3.8 3.8 0 0 1 7-2.1 3.8 3.8 0 0 1 7 2.1c0 4.7-7 9-7 9z" fill={PINK} stroke={PINK} />
  </svg>
);
const IcoTooth: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill="none" stroke={WINE} strokeWidth={3.2} strokeLinecap="round" strokeLinejoin="round">
    <path d="M15 8c-5 0-8 4-8 9 0 6 3 9 4 15 .8 5 2 9 5 9 3.5 0 3-9 8-9s4.5 9 8 9c3 0 4.2-4 5-9 1-6 4-9 4-15 0-5-3-9-8-9-4 0-6 2-9 2s-5-2-9-2z" />
    <path d="M40 4v6M37 7h6" stroke={ORANGE} />
  </svg>
);
const IcoWhats: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={c}>
    <path d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.3A10 10 0 1 0 12 2zm0 18.2a8.2 8.2 0 0 1-4.2-1.2l-.3-.2-3 .8.8-2.9-.2-.3A8.2 8.2 0 1 1 12 20.2zm4.5-6.1c-.2-.1-1.5-.7-1.7-.8-.2-.1-.4-.1-.6.1l-.8 1c-.1.2-.3.2-.5.1a6.7 6.7 0 0 1-3.3-2.9c-.2-.4.2-.4.7-1.3.1-.2 0-.3 0-.4l-.8-1.8c-.2-.5-.4-.4-.6-.4h-.5a1 1 0 0 0-.7.3 3 3 0 0 0-.9 2.2 5.2 5.2 0 0 0 1.1 2.8 11.9 11.9 0 0 0 4.6 4c1.7.7 2.4.8 3.2.7.5-.1 1.5-.6 1.8-1.2.2-.6.2-1.1.1-1.2l-.3-.2z" />
  </svg>
);
const IcoPin: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={c}><path d="M12 2a7.5 7.5 0 0 0-7.5 7.5c0 5.6 7.5 12.5 7.5 12.5s7.5-6.9 7.5-12.5A7.5 7.5 0 0 0 12 2zm0 10.2a2.7 2.7 0 1 1 0-5.4 2.7 2.7 0 0 1 0 5.4z" /></svg>
);
const IcoCard: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill="none" stroke={c} strokeWidth={3.4} strokeLinecap="round" strokeLinejoin="round">
    <rect x={5} y={11} width={38} height={27} rx={5} /><path d="M5 19h38M12 30h9" />
  </svg>
);

// ───────── adesivos animados (entram e ficam) ─────────
const Spark: React.FC<{ t: number; at: number; x: number; y: number; s: number; c: string }> = ({ t, at, x, y, s, c }) => {
  const e = pop(t, at, 0.45);
  if (e <= 0) return null;
  return (
    <svg width={s} height={s} viewBox="0 0 24 24" style={{ position: "absolute", left: x - s / 2, top: y - s / 2, opacity: Math.min(1, e * 2), transform: `scale(${e.toFixed(3)}) rotate(${((1 - e) * 90 + (t - at) * 20).toFixed(1)}deg)` }}>
      <path d="M12 0c1 6.5 5.5 11 12 12-6.5 1-11 5.5-12 12-1-6.5-5.5-11-12-12C6.5 11 11 6.5 12 0z" fill={c} />
    </svg>
  );
};
const Heart: React.FC<{ t: number; at: number; x: number; y: number; s: number; c: string; r?: number }> = ({ t, at, x, y, s, c, r = 0 }) => {
  const e = pop(t, at, 0.5);
  if (e <= 0) return null;
  return (
    <svg width={s} height={s} viewBox="0 0 24 24" style={{ position: "absolute", left: x - s / 2, top: y - s / 2, opacity: Math.min(1, e * 2), transform: `translateY(${((1 - e) * 60).toFixed(1)}px) scale(${e.toFixed(3)}) rotate(${(r + (1 - e) * -30).toFixed(1)}deg)`, filter: "drop-shadow(0 8px 16px rgba(126,22,48,0.3))" }}>
      <path d="M12 21s-8.5-5.3-8.5-11.2A4.8 4.8 0 0 1 12 6.6a4.8 4.8 0 0 1 8.5 3.2C20.5 15.7 12 21 12 21z" fill={c} stroke="#FFFFFF" strokeWidth={1.6} />
    </svg>
  );
};
// confete que estoura numa palavra e cai
const CONF = Array.from({ length: 26 }, (_, i) => ({ a: (i / 26) * Math.PI * 2 + (i % 3) * 0.3, v: 500 + ((i * 137) % 400), c: [PINK, LEAF, ORANGE, PINK_SOFT, WINE][i % 5], w: 18 + (i % 4) * 6, r: (i * 47) % 360 }));
const Confetti: React.FC<{ t: number; at: number; x: number; y: number }> = ({ t, at, x, y }) => {
  const d = t - at;
  if (d < 0 || d > 1.6) return null;
  return (
    <>
      {CONF.map((p, i) => {
        const px = x + Math.cos(p.a) * p.v * Math.min(d, 0.5) * (1 - Math.min(d, 0.5));
        const py = y + Math.sin(p.a) * p.v * Math.min(d, 0.5) * (1 - Math.min(d, 0.5)) * 1.4 + 700 * Math.max(0, d - 0.25) ** 2;
        return <div key={i} style={{ position: "absolute", left: px, top: py, width: p.w, height: p.w * 0.55, borderRadius: 4, background: p.c, opacity: 1 - lin(t, at + 1.0, at + 1.6), transform: `rotate(${(p.r + d * 540).toFixed(0)}deg)` }} />;
      })}
    </>
  );
};
// título cinético em fundo liso: palavras entram com escala e giro e ficam
const Kinetic: React.FC<{ t: number; top: number; size: number; items: [React.ReactNode, number, boolean?][] }> = ({ t, top, size, items }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, textAlign: "center" }}>
    {items.map(([txt, at, hi], i) => {
      const e = pop(t, at - 0.06, 0.42);
      return (
        <div key={i} style={{ fontFamily: SERIF, fontWeight: 800, fontSize: size, lineHeight: 1.06, letterSpacing: -2, color: hi ? PINK : WINE, whiteSpace: "nowrap", opacity: Math.min(1, e * 2.5), transform: `scale(${(0.4 + 0.6 * e).toFixed(3)}) rotate(${((1 - e) * (i % 2 ? 8 : -8)).toFixed(2)}deg)` }}>{txt}</div>
      );
    })}
  </div>
);

// ───────── M1 · abertura cinética com o mascote ─────────
const Abertura: React.FC<{ t: number }> = ({ t }) => {
  const m = pop(t, -0.15, 0.55);
  const cam = interpolate(t, [-0.2, A1 + 0.3], [0, 1], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      <AbsoluteFill style={{ transform: `scale(${(1.06 - 0.06 * cam).toFixed(4)}) rotate(${(-3 + 3 * cam).toFixed(2)}deg)`, transformOrigin: "540px 960px" }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 480, display: "flex", justifyContent: "center" }}>
          <Img src={staticFile("anaultrafocus/simbolo.png")} style={{ width: 680, opacity: Math.min(1, m * 2), transform: `translateY(${((1 - m) * -500).toFixed(1)}px) scale(${(0.5 + 0.5 * m).toFixed(3)}) rotate(${((1 - m) * 25).toFixed(1)}deg)` }} />
        </div>
        <Spark t={t} at={0.1} x={170} y={500} s={100} c={ORANGE} />
        <Spark t={t} at={0.3} x={910} y={470} s={76} c={PINK} />
        <Spark t={t} at={0.5} x={930} y={960} s={60} c={LEAF} />
        <Spark t={t} at={0.7} x={150} y={980} s={64} c={PINK_SOFT} />
        <Kinetic t={t} top={1130} size={124} items={[["O sorriso", 0.07], ["dos pequenos", 0.63, true]]} />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── V1 · o balão (abre em círculo a partir do mascote) ─────────
const Balao: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill>
    <Clip t={t} a={A1} b={A2} src="balao" zoom={[1.2, 1.06]} origin="30% 45%" />
    <Shade />
    <Heart t={t} at={1.5} x={860} y={260} s={130} c={PINK} r={12} />
    <Spark t={t} at={1.7} x={720} y={200} s={70} c={CREAM} />
    <Lettering t={t} lines={[{ text: "merece cuidado", at: 1.13 }, { text: <><Hi>desde cedo</Hi></>, at: 1.89 }]} size={100} />
  </AbsoluteFill>
);

// ───────── M2 · acompanhamento: a agenda do sorriso ─────────
const Agenda: React.FC<{ t: number }> = ({ t }) => {
  const cal = pop(t, A2 - 0.1, 0.55);
  const cam = interpolate(t, [A2, A3 + 0.3], [0, 1], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: BLUSH }}>
      <AbsoluteFill style={{ transform: `scale(${(1.08 - 0.08 * cam).toFixed(4)}) rotate(${(2 - 2 * cam).toFixed(2)}deg)`, transformOrigin: "540px 1000px" }}>
        <Kinetic t={t} top={200} size={96} items={[["Acompanhamento", 2.99], ["odontológico", 3.77, true]]} />
        <div style={{ position: "absolute", left: 120, right: 120, top: 520, height: 1000, borderRadius: 56, background: "#FFFFFF", boxShadow: SHADOW_D, overflow: "hidden", opacity: Math.min(1, cal * 2), transform: `translateY(${((1 - cal) * 300).toFixed(1)}px) rotate(${((1 - cal) * -6).toFixed(2)}deg)` }}>
          <div style={{ height: 170, background: WINE, display: "flex", alignItems: "center", justifyContent: "center", gap: 20 }}>
            <Img src={staticFile("anaultrafocus/simbolo.png")} style={{ height: 96, filter: "brightness(0) invert(1)" }} />
            <span style={{ fontFamily: SERIF, fontWeight: 800, fontSize: 64, color: CREAM }}>Retornos</span>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 28, padding: "50px 56px" }}>
            {Array.from({ length: 9 }, (_, i) => {
              const at = 3.05 + i * 0.14;
              const e = pop(t, at, 0.4);
              const done = i < 8;
              return (
                <div key={i} style={{ height: 210, borderRadius: 34, background: e > 0.5 && done ? PINK_SOFT : "#F6EEF0", display: "flex", alignItems: "center", justifyContent: "center", position: "relative" }}>
                  <div style={{ transform: `scale(${(0.5 + 0.5 * e).toFixed(3)})`, opacity: Math.min(1, e * 2) }}>
                    {done ? (
                      <svg width={96} height={96} viewBox="0 0 24 24"><circle cx={12} cy={12} r={11} fill={i % 2 ? PINK : WINE} /><path d="M7 12.5l3.2 3.2L17 9" stroke={CREAM} strokeWidth={2.6} fill="none" strokeLinecap="round" strokeLinejoin="round" /></svg>
                    ) : <IcoTooth s={96} />}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── M3 · prevenção: o dente escovado ─────────
const BUB = Array.from({ length: 14 }, (_, i) => ({ x: 330 + ((i * 97) % 420), y: 660 + ((i * 61) % 360), at: 4.55 + i * 0.12, s: 26 + (i % 4) * 12 }));
const Dente: React.FC<{ t: number }> = ({ t }) => {
  const d = pop(t, A3 - 0.1, 0.55);
  const brushIn = k(t, 4.45, 0.35);
  const brushOut = k(t, 6.1, 0.3);
  const scrub = Math.sin((t - 4.5) * 15) * 120;
  const shine = lin(t, 6.0, 6.5);
  const shield = pop(t, 4.9, 0.5);
  const cam = interpolate(t, [A3, A4 + 0.3], [0, 1], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      <AbsoluteFill style={{ transform: `scale(${(1 + 0.1 * cam).toFixed(4)}) translateY(${(20 - 40 * cam).toFixed(1)}px)`, transformOrigin: "540px 900px" }}>
        {/* dente sorridente desenhado */}
        <div style={{ position: "absolute", left: 540 - 300, top: 430, width: 600, height: 640, opacity: Math.min(1, d * 2), transform: `scale(${(0.5 + 0.5 * d).toFixed(3)})` }}>
          <svg width={600} height={640} viewBox="0 0 48 52">
            <path d="M15 4c-6 0-11 4.5-11 11 0 7.5 3.6 11 4.8 18.5 1 6.5 2.6 14.5 6.4 14.5 4.2 0 3.6-12 8.8-12s4.6 12 8.8 12c3.8 0 5.4-8 6.4-14.5C40.4 26 44 22.5 44 15 44 8.5 39 4 33 4c-4.6 0-6.4 2.4-9 2.4S19.6 4 15 4z" fill="#FFFFFF" stroke={WINE} strokeWidth={1.8} strokeLinejoin="round" />
            <path d="M17 18.5q1.6-2 3.2 0M27.8 18.5q1.6-2 3.2 0" stroke={WINE} strokeWidth={1.4} fill="none" strokeLinecap="round" />
            <circle cx={16.2} cy={23} r={1.8} fill={PINK_SOFT} /><circle cx={31.8} cy={23} r={1.8} fill={PINK_SOFT} />
            <path d="M20.5 23q3.5 3.4 7 0" stroke={WINE} strokeWidth={1.4} fill="none" strokeLinecap="round" />
          </svg>
          {/* brilho no "cuidado" */}
          {shine > 0 && shine < 1 ? <div style={{ position: "absolute", left: 0, right: 0, top: 0, bottom: 0, background: `linear-gradient(110deg, rgba(255,255,255,0) ${(shine * 140 - 40).toFixed(0)}%, rgba(255,255,255,0.9) ${(shine * 140 - 25).toFixed(0)}%, rgba(255,255,255,0) ${(shine * 140 - 10).toFixed(0)}%)`, mixBlendMode: "screen" }} /> : null}
        </div>
        {/* espuma */}
        {BUB.map((b, i) => {
          const e = pop(t, b.at, 0.3);
          const out = lin(t, 6.05, 6.35);
          return e > 0 ? <div key={i} style={{ position: "absolute", left: b.x, top: b.y - (t - b.at) * 40, width: b.s, height: b.s, borderRadius: b.s, border: `4px solid ${PINK_SOFT}`, background: "rgba(255,255,255,0.7)", opacity: Math.min(1, e * 2) * (1 - out), transform: `scale(${e.toFixed(3)})` }} /> : null;
        })}
        {/* escova */}
        <div style={{ position: "absolute", left: 540 - 330 + scrub, top: 660 + Math.cos((t - 4.5) * 15) * 20, opacity: brushIn * (1 - brushOut), transform: `translateX(${((1 - brushIn) * 700 + brushOut * 700).toFixed(1)}px) rotate(-18deg)` }}>
          <svg width={660} height={150} viewBox="0 0 110 25">
            <rect x={30} y={9} width={78} height={9} rx={4.5} fill={PINK} />
            <rect x={6} y={10} width={28} height={7} rx={3} fill={PINK} />
            {Array.from({ length: 7 }, (_, j) => <rect key={j} x={7 + j * 3.6} y={1} width={2.4} height={9} rx={1} fill={j % 2 ? "#FFFFFF" : "#BFE3F0"} stroke="#9CCBE0" strokeWidth={0.4} />)}
          </svg>
        </div>
        {/* escudo da prevenção */}
        <div style={{ position: "absolute", left: 760, top: 380, width: 200, height: 200, borderRadius: 100, background: "#FFFFFF", boxShadow: SHADOW, display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, shield * 2), transform: `scale(${shield.toFixed(3)}) rotate(${((1 - shield) * -40).toFixed(1)}deg)` }}>
          <IcoShield s={130} />
        </div>
        <Kinetic t={t} top={1240} size={136} items={[["Prevenção", 4.96], ["e cuidado", 5.82, true]]} />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── V2 · exame: saúde bucal desde os primeiros anos ─────────
const Exame: React.FC<{ t: number }> = ({ t }) => {
  const chip = pop(t, 6.45, 0.45);
  return (
    <AbsoluteFill>
      <Clip t={t} a={A4} b={A5} src="exame" zoom={[1.04, 1.16]} origin="50% 55%" />
      <Shade />
      <div style={{ position: "absolute", left: 0, right: 0, top: 1215, display: "flex", justifyContent: "center", opacity: Math.min(1, chip * 2) }}>
        <div style={{ display: "flex", alignItems: "center", gap: 16, padding: "16px 40px 16px 22px", borderRadius: 999, background: PINK, boxShadow: SHADOW_D, transform: `scale(${(0.5 + 0.5 * chip).toFixed(3)})` }}>
          <div style={{ width: 78, height: 78, borderRadius: 39, background: CREAM, display: "flex", alignItems: "center", justifyContent: "center" }}><IcoTooth s={58} /></div>
          <span style={{ fontFamily: SANS, fontWeight: 800, fontSize: 54, color: CREAM, whiteSpace: "nowrap" }}>Saúde bucal</span>
        </div>
      </div>
      <Lettering t={t} top={1400} lines={[{ text: "desde os", at: 7.58 }, { text: <><Hi>primeiros anos</Hi></>, at: 7.96 }]} size={100} />
    </AbsoluteFill>
  );
