// ───────── trocas ─────────
type Tr = React.FC<{ t: number; at: number; children: React.ReactNode }>;
const ease = (t: number, at: number, d = 0.44) => interpolate(t, [at - d / 2, at + d / 2], [0, 1], { ...cl, easing: INOUT });
const Soft: Tr = ({ t, at, children }) => {
  const e = ease(t, at, 0.4);
  return <AbsoluteFill style={{ opacity: e, filter: e < 1 ? `blur(${((1 - e) * 20).toFixed(1)}px)` : undefined, transform: `scale(${(1.06 - 0.06 * e).toFixed(4)})` }}>{children}</AbsoluteFill>;
};
const Circle: Tr = ({ t, at, children }) => <AbsoluteFill style={{ clipPath: `circle(${(ease(t, at, 0.42) * 120).toFixed(1)}% at 50% 28%)` }}>{children}</AbsoluteFill>;
const Wipe: Tr = ({ t, at, children }) => <AbsoluteFill style={{ clipPath: `inset(${((1 - ease(t, at)) * 100).toFixed(2)}% 0 0 0 round 60px 60px 0 0)` }}>{children}</AbsoluteFill>;
const SlideL: Tr = ({ t, at, children }) => <AbsoluteFill style={{ transform: `translateX(${((1 - ease(t, at)) * -1080).toFixed(1)}px)` }}>{children}</AbsoluteFill>;
const SlideUp: Tr = ({ t, at, children }) => <AbsoluteFill style={{ transform: `translateY(${((1 - ease(t, at)) * 1920).toFixed(1)}px)` }}>{children}</AbsoluteFill>;
const Zoom: Tr = ({ t, at, children }) => {
  const e = ease(t, at, 0.4);
  return <AbsoluteFill style={{ opacity: e, transform: `scale(${(0.8 + 0.2 * e).toFixed(4)})` }}>{children}</AbsoluteFill>;
};
const Sweep: React.FC<{ t: number; at: number; c: string }> = ({ t, at, c }) => {
  const p = lin(t, at - 0.28, at + 0.28);
  if (p <= 0 || p >= 1) return null;
  return <div style={{ position: "absolute", top: -300, bottom: -300, width: 260, left: -400 + p * 1900, background: c, transform: "rotate(12deg)", opacity: 0.9 }} />;
};

