    [-1, A1, Abertura, null], [A1, A2, Balao, Circle], [A2, A3, Agenda, Wipe], [A3, A4, Dente, SlideL], [A4, A5, Exame, Zoom],
    [A5, A7, Carinho2, Soft], [A7, A8, Dra2, Wipe], [A8, A9, Convenio2, SlideL], [A9, A10, Whats, SlideUp], [A10, 99, Fecho2, Zoom],
  ];
  return (
    <AbsoluteFill style={{ background: CREAM }}>
      {scenes.map(([a, b, S, W], i) => {
        if (t < a - 0.3 || t > b + 0.3) return null;
        return W ? <W key={i} t={t} at={a}><S t={t} /></W> : <AbsoluteFill key={i}><S t={t} /></AbsoluteFill>;
      })}
      <Sweep t={t} at={A2} c={PINK_SOFT} />
      <Sweep t={t} at={A7} c={LEAF} />
    </AbsoluteFill>
  );
};

